'use client'

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
} from 'react'
import { CircularGalleryEngine } from './circular-gallery.engine'

export interface CircularGalleryItem {
  image: string
  title: string
  alt?: string
}

export interface CircularGalleryOptions {
  radius: number
  itemWidth: number
  itemHeight: number
  bend: number
  count: number
  zoom: number
  zoomOffset: number
  speed: number
  smoothing: number
  inertia: boolean
  snap: boolean
  hover: boolean
  autoplay: boolean
  autoplaySpeed: number
}

export interface CircularGalleryProps extends Partial<CircularGalleryOptions> {
  items: CircularGalleryItem[]
  onActiveChange?: (index: number) => void
  className?: string
  style?: CSSProperties
}

export const circularGalleryDefaults: CircularGalleryOptions = {
  radius: 224,
  itemWidth: 40,
  itemHeight: 45,
  bend: 1,
  count: 25,
  zoom: 5,
  zoomOffset: 0,
  speed: 0.5,
  smoothing: 1,
  inertia: true,
  snap: false,
  hover: true,
  autoplay: false,
  autoplaySpeed: 0.4,
}

const DEG = Math.PI / 180
const MAX_DT = 1 / 30
const CARD_PERSPECTIVE = 1000
const CARD_RADIUS = 4
const WHEEL_CLAMP = 400
const WHEEL_UNIT = 120
const MOTION_QUERY = '(prefers-reduced-motion: reduce)'

interface DragState {
  active: boolean
  x: number
  y: number
  angle: number
}

function subscribeMotion(onChange: () => void) {
  const query = window.matchMedia(MOTION_QUERY)
  query.addEventListener('change', onChange)
  return () => query.removeEventListener('change', onChange)
}

function useReducedMotion() {
  return useSyncExternalStore(
    subscribeMotion,
    () => window.matchMedia(MOTION_QUERY).matches,
    () => false,
  )
}

function wrapAngle(angle: number) {
  return ((((angle + Math.PI) % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2)) - Math.PI
}

export function CircularGallery({
  items,
  radius = circularGalleryDefaults.radius,
  itemWidth = circularGalleryDefaults.itemWidth,
  itemHeight = circularGalleryDefaults.itemHeight,
  bend = circularGalleryDefaults.bend,
  count = circularGalleryDefaults.count,
  zoom = circularGalleryDefaults.zoom,
  zoomOffset = circularGalleryDefaults.zoomOffset,
  speed = circularGalleryDefaults.speed,
  smoothing = circularGalleryDefaults.smoothing,
  inertia = circularGalleryDefaults.inertia,
  snap = circularGalleryDefaults.snap,
  hover = circularGalleryDefaults.hover,
  autoplay = circularGalleryDefaults.autoplay,
  autoplaySpeed = circularGalleryDefaults.autoplaySpeed,
  onActiveChange,
  className,
  style,
}: CircularGalleryProps) {
  const cards = Math.max(3, Math.round(count))
  const reduced = useReducedMotion()
  const engineRef = useRef<CircularGalleryEngine | null>(null)
  if (!engineRef.current) {
    engineRef.current = new CircularGalleryEngine({
      count: cards,
      radius,
      itemWidth,
      itemHeight,
      hover,
      smoothing,
      inertia,
      snap,
      autoplay,
      autoplaySpeed,
      instant: false,
    })
  }
  const engine = engineRef.current
  const [active, setActive] = useState(0)
  const viewportRef = useRef<HTMLDivElement>(null)
  const stageRef = useRef<HTMLDivElement>(null)
  const ringRef = useRef<HTMLDivElement>(null)
  const captionRef = useRef<HTMLDivElement>(null)
  const cardsRef = useRef<(HTMLDivElement | null)[]>([])
  const layoutRef = useRef({ bend, zoom, zoomOffset })
  const speedRef = useRef(speed)
  const dragRef = useRef<DragState>({ active: false, x: 0, y: 0, angle: 0 })
  const wakeRef = useRef<() => void>(() => {})
  const changeRef = useRef(onActiveChange)

  const wake = useCallback(() => wakeRef.current(), [])

  useEffect(() => {
    changeRef.current = onActiveChange
  }, [onActiveChange])

  useEffect(() => {
    engine.setOptions({
      count: cards,
      radius,
      itemWidth,
      itemHeight,
      hover,
      smoothing,
      inertia,
      snap,
      autoplay,
      autoplaySpeed,
      instant: reduced,
    })
    wake()
  }, [
    engine,
    wake,
    cards,
    radius,
    itemWidth,
    itemHeight,
    hover,
    smoothing,
    inertia,
    snap,
    autoplay,
    autoplaySpeed,
    reduced,
  ])

  useEffect(() => {
    layoutRef.current = { bend, zoom, zoomOffset }
    speedRef.current = speed
    engine.idle = false
    wake()
  }, [engine, wake, bend, zoom, zoomOffset, speed])

  useEffect(() => {
    const viewport = viewportRef.current
    const stage = stageRef.current
    const ring = ringRef.current
    if (!viewport || !stage || !ring) return
    let visible = true
    let frame = 0
    let last = 0
    let lastActive = engine.activeIndex

    const render = () => {
      const layout = layoutRef.current
      const zoomT = engine.zoom
      // Hover fades out as the camera flies in
      const weight = 1 - zoomT
      const fit = engine.fitScale
      const ringSize = engine.options.radius * layout.zoom
      const translate = zoomT * (ringSize * fit + layout.zoomOffset)
      const scale = (fit * (1 + (layout.zoom - 1) * zoomT)) / layout.zoom
      stage.style.transform = `rotate(${engine.twist * weight}deg) rotateX(${engine.tiltX * weight}deg) rotateY(${engine.tiltY * weight}deg)`
      ring.style.transform = `translate3d(0, ${translate}px, 0) scale(${scale})`
      const perspective = CARD_PERSPECTIVE * layout.zoom
      const nodes = cardsRef.current
      for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i]
        const motion = engine.cards[i]
        if (!node || !motion) continue
        const angle = engine.cardAngle(i)
        const push = motion.push * weight * layout.zoom
        const flip = motion.flip * weight
        const swell = 1 + (motion.swell - 1) * weight
        node.style.transform = `perspective(${perspective}px) rotate(${angle}deg) translate3d(0, ${-(ringSize + push)}px, 0) rotate(${-angle * (1 - layout.bend)}deg) rotateY(${flip}deg) scale(${swell})`
      }
      const caption = captionRef.current
      if (caption) caption.style.opacity = String(Math.min(Math.max((zoomT - 0.6) / 0.4, 0), 1))
      if (engine.activeIndex !== lastActive) {
        lastActive = engine.activeIndex
        setActive(lastActive)
        changeRef.current?.(lastActive)
      }
    }

    const loop = (now: number) => {
      frame = 0
      if (!visible) return
      const dt = last ? Math.min((now - last) / 1000, MAX_DT) : 1 / 60
      last = now
      engine.tick(dt)
      render()
      if (!engine.idle) frame = requestAnimationFrame(loop)
      else last = 0
    }

    const start = () => {
      if (frame || !visible) return
      last = 0
      frame = requestAnimationFrame(loop)
    }

    const stop = () => {
      if (frame) cancelAnimationFrame(frame)
      frame = 0
      last = 0
    }

    wakeRef.current = start

    const onWheel = (e: WheelEvent) => {
      // At rest an upward wheel goes back to the page
      if (e.deltaY < 0 && engine.travelTarget <= 0) return
      e.preventDefault()
      const unit = e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? viewport.clientHeight || 800 : 1
      const px = Math.min(Math.max(e.deltaY * unit, -WHEEL_CLAMP), WHEEL_CLAMP)
      engine.wheel((px * speedRef.current) / WHEEL_UNIT)
      start()
    }
    viewport.addEventListener('wheel', onWheel, { passive: false })

    const resize = new ResizeObserver(([entry]) => {
      const rect = entry?.contentRect
      engine.resize(rect?.width ?? 0, rect?.height ?? 0)
      render()
      start()
    })
    resize.observe(viewport)

    const intersection = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? true
      if (visible) start()
      else stop()
    })
    intersection.observe(viewport)

    const onVisibility = () => {
      if (document.hidden) stop()
      else start()
    }
    document.addEventListener('visibilitychange', onVisibility)

    return () => {
      stop()
      viewport.removeEventListener('wheel', onWheel)
      resize.disconnect()
      intersection.disconnect()
      document.removeEventListener('visibilitychange', onVisibility)
      wakeRef.current = () => {}
    }
  }, [engine])

  const pointerAngle = (e: PointerEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect()
    const x = e.clientX - rect.left - rect.width / 2
    const y = e.clientY - rect.top - rect.height / 2
    return { x, y, angle: Math.atan2(x, -y), distance: Math.hypot(x, y) }
  }

  // Touch gets no flip: it would fire once and stick
  const trackPointer = (e: PointerEvent<HTMLDivElement>) => {
    const { x, y } = pointerAngle(e)
    engine.setPointer(x, y, e.pointerType !== 'touch')
    wake()
  }

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.pointerType === 'mouse' && e.button !== 0) return
    e.currentTarget.setPointerCapture(e.pointerId)
    const point = pointerAngle(e)
    dragRef.current = { active: true, x: point.x, y: point.y, angle: point.angle }
    engine.dragStart()
    trackPointer(e)
  }

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    trackPointer(e)
    const drag = dragRef.current
    if (!drag.active) return
    const point = pointerAngle(e)
    const layout = layoutRef.current
    const ringPx = engine.options.radius * engine.fitScale * (1 + (layout.zoom - 1) * engine.zoom)
    let delta: number
    if (engine.zoom < 0.5 && point.distance > ringPx * 0.25) {
      // Around the ring the pointer angle drives the rotation directly
      delta = -wrapAngle(point.angle - drag.angle) / (engine.spacing * DEG)
    } else {
      delta = -(point.x - drag.x) / ((Math.PI * 2 * ringPx) / cards)
    }
    dragRef.current = { active: true, x: point.x, y: point.y, angle: point.angle }
    engine.dragMove(delta)
    wake()
  }

  const finishDrag = () => {
    const drag = dragRef.current
    if (!drag.active) return
    drag.active = false
    engine.dragEnd()
    wake()
  }

  const onPointerLeave = () => {
    engine.setPointer(0, 0, false)
    engine.inside = false
    wake()
  }

  const onPointerEnter = () => {
    engine.inside = true
    wake()
  }

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') engine.step(1)
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') engine.step(-1)
    else if (e.key === 'Enter' || e.key === ' ') engine.toggleZoom()
    else if (e.key === 'Escape') engine.zoomOut()
    else return
    e.preventDefault()
    wake()
  }

  const cardWidth = itemWidth * zoom
  const cardHeight = itemHeight * zoom
  const spacing = 360 / cards
  const slots = Array.from({ length: cards }, (_, i) => items[i % Math.max(1, items.length)])
  const activeItem = items[active % Math.max(1, items.length)]

  return (
    <div
      className={['uig-circular-gallery', 'overflow-hidden', className].filter(Boolean).join(' ')}
      style={style}
    >
      <div
        ref={viewportRef}
        role="region"
        aria-roledescription="carousel"
        aria-label="Circular gallery"
        tabIndex={0}
        className="uig-circular-gallery__viewport relative h-full w-full cursor-grab touch-none select-none focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-current active:cursor-grabbing"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={finishDrag}
        onPointerCancel={finishDrag}
        onLostPointerCapture={finishDrag}
        onPointerEnter={onPointerEnter}
        onPointerLeave={onPointerLeave}
        onFocus={onPointerEnter}
        onBlur={onPointerLeave}
        onKeyDown={onKeyDown}
      >
        <div
          ref={stageRef}
          className="uig-circular-gallery__stage absolute top-1/2 left-1/2 h-0 w-0 will-change-transform"
        >
          <div
            ref={ringRef}
            className="uig-circular-gallery__ring absolute h-0 w-0 will-change-transform"
          >
            {slots.map((item, i) => (
              <div
                key={i}
                ref={(element) => {
                  cardsRef.current[i] = element
                }}
                aria-hidden={i !== active}
                className="uig-circular-gallery__card absolute overflow-hidden will-change-transform"
                style={{
                  width: cardWidth,
                  height: cardHeight,
                  left: -cardWidth / 2,
                  top: -cardHeight / 2,
                  borderRadius: CARD_RADIUS * zoom,
                  transform: `perspective(${CARD_PERSPECTIVE * zoom}px) rotate(${i * spacing}deg) translate3d(0, ${-radius * zoom}px, 0)`,
                }}
              >
                {item && (
                  <img
                    src={item.image}
                    alt={item.alt ?? item.title}
                    draggable={false}
                    className="uig-circular-gallery__image block h-full w-full object-cover"
                  />
                )}
              </div>
            ))}
          </div>
        </div>
        <div
          ref={captionRef}
          aria-hidden="true"
          className="uig-circular-gallery__caption pointer-events-none absolute inset-x-0 bottom-6 text-center text-sm font-medium tracking-tight"
          style={{ opacity: 0 }}
        >
          {activeItem?.title}
        </div>
      </div>
      <div className="uig-circular-gallery__live sr-only" aria-live="polite">
        {activeItem?.title}
      </div>
    </div>
  )
}

export interface CircularGalleryEngineOptions {
  count: number
  radius: number
  itemWidth: number
  itemHeight: number
  hover: boolean
  smoothing: number
  inertia: boolean
  snap: boolean
  autoplay: boolean
  autoplaySpeed: number
  instant: boolean
}

export interface CircularGalleryCardMotion {
  flip: number
  flipTarget: number
  swell: number
  swellTarget: number
  push: number
  pushTarget: number
}

type Mode = 'idle' | 'drag' | 'coast' | 'settle'

const DEG = Math.PI / 180
const FLY_IN = 2
const FRICTION = 3
const HANDOVER_SPEED = 1.2
const SPRING = 160
const DAMPING = 2 * Math.sqrt(SPRING)
const WHEEL_PAUSE = 0.12
const HOVER_LERP = 0.15
const FALLOFF = 250
const FLIP = 180
const SWELL = 0.3
const PUSH = 50
const TILT = 15
const TWIST = 5

function smoothstep(t: number) {
  return t * t * (3 - 2 * t)
}

function approach(current: number, target: number, k: number, epsilon: number) {
  const next = current + (target - current) * k
  return Math.abs(target - next) < epsilon ? target : next
}

function makeCard(): CircularGalleryCardMotion {
  return { flip: 0, flipTarget: 0, swell: 1, swellTarget: 1, push: 0, pushTarget: 0 }
}

export class CircularGalleryEngine {
  travel = 0
  travelTarget = 0
  offset = 0
  offsetTarget = 0
  velocity = 0
  pointerX = 0
  pointerY = 0
  pointerActive = false
  width = 0
  height = 0
  cards: CircularGalleryCardMotion[] = []
  tiltX = 0
  tiltY = 0
  twist = 0
  tiltXTarget = 0
  tiltYTarget = 0
  twistTarget = 0
  inside = false
  idle = true
  options: CircularGalleryEngineOptions
  private mode: Mode = 'idle'
  private dragSample = 0
  private sinceWheel = Infinity
  private wheelSnapPending = false
  private hoverDirty = true
  private hoverRotation = 0

  constructor(options: CircularGalleryEngineOptions) {
    this.options = options
    this.syncCards()
  }

  get spacing() {
    return 360 / Math.max(1, this.options.count)
  }

  // Wheel travel past the fly-in, in cards
  get ride() {
    return Math.max(0, this.travel - FLY_IN)
  }

  // Ring rotation in cards; the card at a whole number sits at twelve o'clock
  get rotation() {
    return this.ride + this.offset
  }

  // 0 at rest, 1 once the first two cards of wheel travel flew the camera in
  get zoom() {
    return smoothstep(Math.min(Math.max(this.travel / FLY_IN, 0), 1))
  }

  // Shrinks the resting ring into the viewport, never past 1:1
  get fitScale() {
    const o = this.options
    const span = 2 * o.radius + Math.hypot(o.itemWidth, o.itemHeight)
    if (!this.width || !this.height || !span) return 1
    return Math.max(0.01, Math.min(1, Math.min(this.width, this.height) / span))
  }

  get activeIndex() {
    const count = Math.max(1, this.options.count)
    return ((Math.round(this.rotation) % count) + count) % count
  }

  cardAngle(index: number) {
    return (index - this.rotation) * this.spacing
  }

  setOptions(next: Partial<CircularGalleryEngineOptions>) {
    this.options = { ...this.options, ...next }
    this.syncCards()
    this.hoverDirty = true
    this.idle = false
  }

  resize(width: number, height: number) {
    this.width = width
    this.height = height
    this.hoverDirty = true
    this.idle = false
  }

  setPointer(x: number, y: number, active: boolean) {
    this.pointerX = x
    this.pointerY = y
    this.pointerActive = active
    this.hoverDirty = true
    this.idle = false
  }

  wheel(deltaCards: number) {
    if (this.mode === 'drag') return
    if (this.mode !== 'idle') {
      this.mode = 'idle'
      this.velocity = 0
      this.offsetTarget = this.offset
    }
    this.travelTarget = Math.max(0, this.travelTarget + deltaCards)
    this.sinceWheel = 0
    this.wheelSnapPending = true
    this.idle = false
  }

  dragStart() {
    this.mode = 'drag'
    this.velocity = 0
    this.dragSample = 0
    this.idle = false
  }

  dragMove(deltaCards: number) {
    if (this.mode !== 'drag') return
    this.offset += deltaCards
    this.offsetTarget = this.offset
    this.dragSample += deltaCards
  }

  dragEnd() {
    if (this.mode !== 'drag') return
    if (this.options.instant || !this.options.inertia) {
      this.settleTo(this.options.snap ? this.nearest(this.offset) : this.offset)
      return
    }
    const projected = this.offset + this.velocity / FRICTION
    this.offsetTarget = this.options.snap ? this.nearest(projected) : projected
    this.mode = 'coast'
    this.idle = false
  }

  step(direction: number) {
    if (this.mode === 'drag') return
    this.velocity = 0
    this.mode = 'idle'
    this.offsetTarget = this.nearest(this.offsetTarget) + direction
    this.idle = false
  }

  // Keyboard zoom keeps the rotation so the same card stays in front
  toggleZoom() {
    if (this.mode === 'drag') return
    if (this.travelTarget >= 1) {
      this.offsetTarget += this.rideTarget
      this.travelTarget = 0
    } else {
      this.travelTarget = FLY_IN
    }
    this.wheelSnapPending = false
    this.idle = false
  }

  zoomOut() {
    if (this.mode === 'drag' || this.travelTarget === 0) return
    this.offsetTarget += this.rideTarget
    this.travelTarget = 0
    this.wheelSnapPending = false
    this.idle = false
  }

  tick(dt: number) {
    const o = this.options
    this.sinceWheel += dt
    if (this.wheelSnapPending && this.sinceWheel > WHEEL_PAUSE) {
      this.wheelSnapPending = false
      if (o.snap) {
        this.travelTarget =
          this.travelTarget < 1 ? 0 : Math.max(FLY_IN, Math.round(this.travelTarget))
      }
    }
    const playing = o.autoplay && !o.instant && !this.inside && this.mode === 'idle'
    if (playing) {
      this.offset += o.autoplaySpeed * dt
      this.offsetTarget = this.offset
    }
    const lerp = 0.16 - Math.min(Math.max(o.smoothing, 0), 1) * 0.12
    const k = o.instant ? 1 : 1 - Math.pow(1 - lerp, dt * 60)
    this.travel = approach(this.travel, this.travelTarget, k, 0.0005)
    switch (this.mode) {
      case 'drag': {
        const sampled = this.dragSample / Math.max(dt, 0.001)
        this.velocity += (sampled - this.velocity) * 0.5
        this.dragSample = 0
        break
      }
      case 'coast': {
        this.offset += this.velocity * dt
        this.velocity *= Math.exp(-FRICTION * dt)
        const passed =
          this.velocity > 0 ? this.offset >= this.offsetTarget : this.offset <= this.offsetTarget
        if (passed || Math.abs(this.velocity) < HANDOVER_SPEED) this.mode = 'settle'
        break
      }
      case 'settle': {
        const diff = this.offsetTarget - this.offset
        this.velocity += (SPRING * diff - DAMPING * this.velocity) * dt
        this.offset += this.velocity * dt
        if (Math.abs(diff) < 0.0005 && Math.abs(this.velocity) < 0.01) {
          this.offset = this.offsetTarget
          this.velocity = 0
          this.mode = 'idle'
        }
        break
      }
      default: {
        this.offset = approach(this.offset, this.offsetTarget, k, 0.0005)
      }
    }
    if (this.hoverDirty || this.rotation !== this.hoverRotation) this.aimHover()
    const hk = o.instant ? 1 : 1 - Math.pow(1 - HOVER_LERP, dt * 60)
    this.tiltX = approach(this.tiltX, this.tiltXTarget, hk, 0.01)
    this.tiltY = approach(this.tiltY, this.tiltYTarget, hk, 0.01)
    this.twist = approach(this.twist, this.twistTarget, hk, 0.01)
    let hoverSettled =
      this.tiltX === this.tiltXTarget &&
      this.tiltY === this.tiltYTarget &&
      this.twist === this.twistTarget
    for (const card of this.cards) {
      card.flip = approach(card.flip, card.flipTarget, hk, 0.01)
      card.swell = approach(card.swell, card.swellTarget, hk, 0.0005)
      card.push = approach(card.push, card.pushTarget, hk, 0.01)
      if (
        card.flip !== card.flipTarget ||
        card.swell !== card.swellTarget ||
        card.push !== card.pushTarget
      ) {
        hoverSettled = false
      }
    }
    this.idle =
      this.mode === 'idle' &&
      !playing &&
      !this.wheelSnapPending &&
      this.travel === this.travelTarget &&
      this.offset === this.offsetTarget &&
      hoverSettled
  }

  private get rideTarget() {
    return Math.max(0, this.travelTarget - FLY_IN)
  }

  private syncCards() {
    const count = Math.max(1, this.options.count)
    if (this.cards.length > count) this.cards.length = count
    while (this.cards.length < count) this.cards.push(makeCard())
  }

  // Targets are aimed only when the pointer or the ring moves
  private aimHover() {
    this.hoverDirty = false
    this.hoverRotation = this.rotation
    const o = this.options
    if (!this.pointerActive || !o.hover || o.instant) {
      this.tiltXTarget = 0
      this.tiltYTarget = 0
      this.twistTarget = 0
      for (const card of this.cards) {
        card.flipTarget = 0
        card.swellTarget = 1
        card.pushTarget = 0
      }
      return
    }
    const percentX = this.width ? this.pointerX / (this.width / 2) : 0
    const percentY = this.height ? this.pointerY / (this.height / 2) : 0
    this.tiltYTarget = percentX * TILT
    this.tiltXTarget = -percentY * TILT
    this.twistTarget = (percentX + percentY) * TWIST
    const fit = this.fitScale
    const x = this.pointerX / fit
    const y = this.pointerY / fit
    for (let i = 0; i < this.cards.length; i++) {
      const card = this.cards[i]
      if (!card) continue
      const angle = this.cardAngle(i) * DEG
      const reach = o.radius + card.push
      const distance = Math.hypot(x - reach * Math.sin(angle), y + reach * Math.cos(angle))
      const force = Math.max(0, 1 - distance / FALLOFF)
      card.flipTarget = FLIP * force
      card.swellTarget = 1 + SWELL * force
      card.pushTarget = PUSH * force
    }
  }

  private settleTo(target: number) {
    this.offsetTarget = target
    if (this.options.instant) {
      this.offset = target
      this.velocity = 0
      this.mode = 'idle'
    } else {
      this.mode = 'settle'
    }
    this.idle = false
  }

  // Nearest offset that puts a card exactly at the front
  private nearest(offset: number) {
    return Math.round(this.rideTarget + offset) - this.rideTarget
  }
}
